package mz.bam.seeky.android;

import android.app.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.os.*;import android.view.*;
import java.io.*;import java.util.concurrent.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class)
@Config(manifest=Config.NONE,sdk=33,qualifiers="w720dp-h360dp-land-mdpi",application=Application.class,shadows={PdfLaunchTest.RendererDouble.class,ReaderSharp5153Test.SharpPage.class})
@LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ReaderSharp5153Test {
 @Implements(PdfRenderer.Page.class) public static class SharpPage extends PdfLaunchTest.PageDouble {
  static volatile boolean fail;static volatile CountDownLatch entered,release;static int detailRenders;
  @Implementation protected void render(Bitmap bitmap,Rect clip,Matrix matrix,int mode){
   if(matrix!=null){detailRenders++;if(entered!=null){entered.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new RuntimeException(e);}}if(fail)throw new IllegalStateException("Deliberate detail render failure");}
   Canvas c=new Canvas(bitmap);c.drawColor(Color.WHITE);if(matrix!=null)c.concat(matrix);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(index==0?Color.RED:Color.BLUE);c.drawRect(80,100,120,130,p);p.setColor(Color.BLACK);p.setTextSize(17);for(int y=55;y<790;y+=35)c.drawText("Seeky · Texto nítido durante a leitura · Linha "+y,25,y,p);p.setColor(index==0?Color.RED:Color.BLUE);c.drawRect(80,100,120,130,p);
  }
 }
 ReaderLayout5152Test fixture;ReaderActivity a;ReaderPageView page;
 @Before public void setup()throws Exception{SharpPage.fail=false;SharpPage.entered=SharpPage.release=null;SharpPage.detailRenders=0;fixture=new ReaderLayout5152Test();fixture.open(false);a=fixture.a;page=(ReaderPageView)a.pageList.getChildAt(0);warm();assertNotNull(page.detailTile);}
 @After public void close(){if(SharpPage.release!=null)SharpPage.release.countDown();SharpPage.entered=SharpPage.release=null;SharpPage.fail=false;fixture.close();}
 void warm()throws Exception{for(int n=0;n<3;n++){shadowOf(Looper.getMainLooper()).idleFor(55,TimeUnit.MILLISECONDS);a.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
 void event(int action,float x,float y,long start){MotionEvent e=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,x,y,0);try{a.pageList.dispatchTouchEvent(e);}finally{e.recycle();}}
 Bitmap draw(){Bitmap b=Bitmap.createBitmap(page.getWidth(),page.getHeight(),Bitmap.Config.ARGB_8888);page.draw(new Canvas(b));return b;}
 int pixel(float x,float y){float[] point={x,y};page.matrix.mapPoints(point);Bitmap b=draw();try{return b.getPixel(Math.round(point[0]),Math.round(point[1]));}finally{b.recycle();}}
 @Test public void touchWithoutMovementKeepsTheSameSharpPixels()throws Exception{Bitmap frame=page.detailTile,before=draw();int serial=page.tileSerial;long t=SystemClock.uptimeMillis();event(MotionEvent.ACTION_DOWN,330,140,t);event(MotionEvent.ACTION_MOVE,330,140,t);Bitmap during=draw();assertSame(frame,page.detailTile);assertEquals(serial,page.tileSerial);assertTrue("touch must not fall back to preview",before.sameAs(during));event(MotionEvent.ACTION_UP,330,140,t);before.recycle();during.recycle();}
 @Test public void verticalDragRetainsSharpFrameWithCorrectPositionAndNoGhost()throws Exception{Bitmap frame=page.detailTile;float[] old={100,115};page.matrix.mapPoints(old);long t=SystemClock.uptimeMillis();event(MotionEvent.ACTION_DOWN,330,170,t);event(MotionEvent.ACTION_MOVE,330,140,t);assertSame(frame,page.detailTile);assertEquals(0xffff252a,pixel(100,115));Bitmap during=draw();assertEquals("old glyph position must be cleared",Color.WHITE,during.getPixel(Math.round(old[0]),Math.round(old[1])));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+"-5153-during-drag.png")){during.compress(Bitmap.CompressFormat.PNG,100,out);}during.recycle();event(MotionEvent.ACTION_UP,330,140,t);}
 @Test public void zoomKeepsTheFrameAlignedUntilReplacementIsReady()throws Exception{Bitmap before=page.detailTile;page.zoom(1.15f);assertSame(before,page.detailTile);assertEquals(0xffff252a,pixel(100,115));assertEquals(Color.WHITE,pixel(75,115));warm();assertNotSame(before,page.detailTile);assertEquals(0xffff252a,pixel(100,115));}
 @Test public void sharpFramesCanRefreshBeforeTheFingerStops()throws Exception{Bitmap first=page.detailTile;long t=SystemClock.uptimeMillis();event(MotionEvent.ACTION_DOWN,330,180,t);event(MotionEvent.ACTION_MOVE,330,170,t);warm();assertNotSame("refresh while gesture still held",first,page.detailTile);Bitmap second=page.detailTile;event(MotionEvent.ACTION_MOVE,330,155,t);warm();assertNotSame(second,page.detailTile);assertEquals(0xffff252a,pixel(100,115));event(MotionEvent.ACTION_UP,330,155,t);}
 @Test public void frameRenderedDuringMovementIsRepositionedInsteadOfDiscarded()throws Exception{Bitmap first=page.detailTile;SharpPage.entered=new CountDownLatch(1);SharpPage.release=new CountDownLatch(1);page.ty-=5;page.apply();shadowOf(Looper.getMainLooper()).idleFor(55,TimeUnit.MILLISECONDS);assertTrue(SharpPage.entered.await(10,TimeUnit.SECONDS));for(int i=0;i<20;i++){page.ty-=1;page.apply();}assertTrue(page.detailRendering);SharpPage.release.countDown();a.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();assertNotSame(first,page.detailTile);assertTrue("one update follows the completed render",page.detailScheduled);assertEquals(0xffff252a,pixel(100,115));}
 @Test public void renderFailureKeepsLastSharpFrameAndDoesNotRetryForever()throws Exception{Bitmap good=page.detailTile;int count=SharpPage.detailRenders;SharpPage.fail=true;page.ty-=15;page.apply();warm();assertSame(good,page.detailTile);assertFalse(page.detailRendering);assertFalse(page.detailScheduled);assertEquals(count+1,SharpPage.detailRenders);assertEquals(0xffff252a,pixel(100,115));}
 @Test public void changingPagesClearsThePreviousSharpImage()throws Exception{a.setPage(1);fixture.layout(720,360);page=(ReaderPageView)a.pageList.getChildAt(0);warm();assertEquals(1,a.currentPage);assertEquals(0xff2325ff,pixel(100,115));assertFalse(page.detailRendering);}
 @Test public void pageChangeDiscardsAnOlderRenderThatFinishesLate()throws Exception{SharpPage.entered=new CountDownLatch(1);SharpPage.release=new CountDownLatch(1);page.ty-=5;page.apply();shadowOf(Looper.getMainLooper()).idleFor(55,TimeUnit.MILLISECONDS);assertTrue(SharpPage.entered.await(10,TimeUnit.SECONDS));a.setPage(1);a.root.measure(View.MeasureSpec.makeMeasureSpec(720,1073741824),View.MeasureSpec.makeMeasureSpec(360,1073741824));a.root.layout(0,0,720,360);page=(ReaderPageView)a.pageList.getChildAt(0);assertEquals(1,page.getTag());assertNull(page.detailTile);SharpPage.release.countDown();fixture.layout(720,360);page=(ReaderPageView)a.pageList.getChildAt(0);warm();assertEquals(0xff2325ff,pixel(100,115));}
 @Test public void detailMemoryStaysBoundedInALargeViewport()throws Exception{fixture.layout(1400,1000);page=(ReaderPageView)a.pageList.getChildAt(0);warm();assertTrue((long)page.detailTile.getWidth()*page.detailTile.getHeight()<=900000);assertTrue(page.detailTile.getAllocationByteCount()<=3600000);assertEquals(0xffff252a,pixel(100,115));}
}
